SELECT project_type, project_id, project_name, price, duration
FROM agent_v3_project_catalog_view
WHERE agent_v3_project_catalog_view.store_id = ANY(:allowedStoreIds) AND (project_name = '***') LIMIT 100;

SELECT price AS price, duration AS duration
FROM agent_v3_project_catalog_view
WHERE agent_v3_project_catalog_view.store_id = ANY(:allowedStoreIds) AND (project_name = '***') LIMIT 1;

SELECT scope_type, COUNT(DISTINCT promotion_id) AS promotion_count
FROM agent_v3_promotion_offer_view WHERE agent_v3_promotion_offer_view.store_id = ANY(:allowedStoreIds) GROUP BY scope_type
LIMIT 100;

