SELECT customer_id, customer_name_masked, churn_risk_level, COUNT(DISTINCT customer_id) AS customer_count
FROM ask_data_customer_lifecycle_view WHERE ask_data_customer_lifecycle_view.store_id = ANY(:allowedStoreIds) GROUP BY customer_id, customer_name_masked, churn_risk_level
LIMIT 100;

SELECT COUNT(DISTINCT customer_id) AS customer_count
FROM ask_data_customer_lifecycle_view
WHERE ask_data_customer_lifecycle_view.store_id = ANY(:allowedStoreIds) AND (churn_risk_level IN ('***', '***')) LIMIT 1;

SELECT COUNT(DISTINCT customer_id) AS customer_count, SUM(total_paid_amount) AS total_paid_amount
FROM ask_data_customer_profile_summary_view
WHERE ask_data_customer_profile_summary_view.store_id = ANY(:allowedStoreIds) AND (member_level = '***') LIMIT 1;

SELECT transfer_id, transfer_no, product_count
FROM ask_data_transfer_status_view WHERE ask_data_transfer_status_view.store_id = ANY(:allowedStoreIds) ORDER BY product_count DESC
LIMIT 10;

SELECT COUNT(DISTINCT transfer_id) AS transfer_count
FROM ask_data_transfer_status_view
WHERE ask_data_transfer_status_view.store_id = ANY(:allowedStoreIds) AND (status IN ('***', '***', '***')) LIMIT 1;
